import{_ as e,c as a,o as t,a as i}from"./app.19f3f8f0.js";const f=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[{"level":2,"title":"Mission","slug":"mission","link":"#mission","children":[]},{"level":2,"title":"How we work","slug":"how-we-work","link":"#how-we-work","children":[]},{"level":2,"title":"Products","slug":"products","link":"#products","children":[]},{"level":2,"title":"Team & culture","slug":"team-culture","link":"#team-culture","children":[]},{"level":2,"title":"Trust & transparency","slug":"trust-transparency","link":"#trust-transparency","children":[]},{"level":2,"title":"Contact","slug":"contact","link":"#contact","children":[]}],"relativePath":"about.md"}'),r={name:"about.md"},s=i('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-hidden="true">#</a></h1><p>TLDR builds digital products that solve real problems through simplicity and focus. We strip away unnecessary features and ship stable, valuable services that people can use every day.</p><hr><h2 id="mission" tabindex="-1">Mission <a class="header-anchor" href="#mission" aria-hidden="true">#</a></h2><ul><li>Simplify problems and focus on what matters.</li><li>Build products that respect users’ time.</li><li>Treat privacy and security as first-class priorities.</li></ul><h2 id="how-we-work" tabindex="-1">How we work <a class="header-anchor" href="#how-we-work" aria-hidden="true">#</a></h2><ul><li>Validate ideas quickly with minimum viable products (MVPs).</li><li>Improve continuously based on user feedback.</li><li>Prefer data-informed decisions.</li></ul><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-hidden="true">#</a></h2><ul><li><strong>EmotionCare:</strong> Personalized comfort and encouragement based on emotional context.</li><li><strong>PackCheck:</strong> Photo-based luggage weight estimation and management.</li><li><strong>SimpleVisionTimer:</strong> A minimal timer that supports focus.</li><li><strong>Lumina:</strong> AI image generation in multiple styles.</li><li><strong>chargeUpEV:</strong> EV efficiency and range estimation.</li></ul><p>See the <a href="/products">Products</a> page for details.</p><hr><h2 id="team-culture" tabindex="-1">Team &amp; culture <a class="header-anchor" href="#team-culture" aria-hidden="true">#</a></h2><ul><li>Small team, high ownership: everyone owns the product end to end.</li><li>Transparent communication: we share outcomes and process openly.</li><li>Automation &amp; documentation: reduce repetition and raise quality.</li></ul><h2 id="trust-transparency" tabindex="-1">Trust &amp; transparency <a class="header-anchor" href="#trust-transparency" aria-hidden="true">#</a></h2><ul><li>Clear <a href="/privacy-policy">Privacy Policy</a> and <a href="/terms">Terms</a>.</li><li>Transparent disclosure of ads and paid features.</li><li>For inquiries and partnerships, use the <a href="/contact">Contact</a> page.</li></ul><hr><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-hidden="true">#</a></h2><ul><li>Support / general: <a href="mailto:main@tl-dr.in" target="_blank" rel="noreferrer">main@tl-dr.in</a></li><li>Location: Remote-first, Asia-based operations</li></ul><p>We stay focused on shipping products that deliver real value.</p>',19),n=[s];function l(o,c,d,u,h,p){return t(),a("div",null,n)}const g=e(r,[["render",l]]);export{f as __pageData,g as default};
